contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 initialSupply, uint256 burnAmount) public {
        require(burnAmount <= initialSupply);
        c = new C(initialSupply, "t", "T");
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool ok = c.burn(burnAmount); if (__ESBMC_reverted()) return;
        assert(ok && c.balanceOf(address(this)) == balBefore - burnAmount && c.totalSupply() == supplyBefore - burnAmount);
    }
    receive() external payable {}
}

